Perturbación 2: ruina espacial (clientes relacionados por cercanía a una semilla) y reinserción por mínimo costo con ruido sobre el gran tour.

```python
from random import Random

from generated.cvrp_tour_opusmodel.model.parts import canonical

COMPONENT = {
    "name": "related_removal_noisy_reinsertion",
    "slot": "perturbation",
    "compatible_skeletons": ["ILS"],
    "requires": [],
    "params": {
        "noise": {"type": "float", "range": [0.0, 1.0]},
        "max_fraction": {"type": "float", "range": [0.05, 0.5]},
    },
}


class RelatedRemovalNoisyReinsertion:
    def __init__(self, problem, noise=0.3, max_fraction=0.3):
        self.problem = problem
        self.inst = problem.inst
        self.noise = float(noise)
        self.max_fraction = float(max_fraction)

    def _ins_cost(self, tour, pos, c):
        dist = self.inst.dist
        prev = tour[pos - 1] if pos > 0 else 0
        nxt = tour[pos] if pos < len(tour) else 0
        return dist(prev, c) + dist(c, nxt) - dist(prev, nxt)

    def perturb(self, sol, strength: float, rng: Random):
        base = list(canonical(sol))
        n = len(base)
        if n < 2:
            return canonical(base)
        dist = self.inst.dist
        cap_k = max(1, int(self.max_fraction * n))
        k = max(1, min(int(round(strength)), cap_k, n - 1))
        seed = rng.choice(base)
        scored = sorted(
            base,
            key=lambda c: (dist(seed, c) * (1.0 + self.noise * rng.random()), c),
        )
        removed = scored[:k]
        rem_set = set(removed)
        tour = [c for c in base if c not in rem_set]
        rng.shuffle(removed)
        for c in removed:
            best_pos, best_val = 0, float("inf")
            for pos in range(len(tour) + 1):
                val = self._ins_cost(tour, pos, c) * (1.0 + self.noise * rng.random())
                if val < best_val:
                    best_val, best_pos = val, pos
            tour.insert(best_pos, c)
        if tour == base:
            i, j = rng.sample(range(n), 2)
            tour = list(base)
            tour[i], tour[j] = tour[j], tour[i]
        return canonical(tour)


def build_component(problem, noise=0.3, max_fraction=0.3):
    return RelatedRemovalNoisyReinsertion(problem, noise=noise, max_fraction=max_fraction)
```

Perturbación 3: decodifica las rutas con Split, aplica cross-exchange de segmentos entre rutas y luego reordena o invierte rutas antes de reconcatenar.

```python
from random import Random

from generated.cvrp_tour_opusmodel.model.parts import canonical, _decode

COMPONENT = {
    "name": "route_cross_exchange_reshuffle",
    "slot": "perturbation",
    "compatible_skeletons": ["ILS"],
    "requires": [],
    "params": {
        "max_seg": {"type": "int", "range": [1, 6]},
        "route_shuffle_prob": {"type": "float", "range": [0.0, 1.0]},
        "route_reverse_prob": {"type": "float", "range": [0.0, 0.5]},
    },
}


class RouteCrossExchangeReshuffle:
    def __init__(self, problem, max_seg=3, route_shuffle_prob=0.5, route_reverse_prob=0.2):
        self.problem = problem
        self.inst = problem.inst
        self.max_seg = int(max_seg)
        self.route_shuffle_prob = float(route_shuffle_prob)
        self.route_reverse_prob = float(route_reverse_prob)

    def _segment(self, r, rng):
        L = len(r)
        length = rng.randint(0, min(self.max_seg, L))
        i = rng.randint(0, L - length)
        return i, i + length

    def perturb(self, sol, strength: float, rng: Random):
        base = list(canonical(sol))
        n = len(base)
        if n < 2:
            return canonical(base)
        routes, _ = _decode(self.inst, tuple(base))
        routes = [list(r) for r in routes if r]
        seen = set(c for r in routes for c in r)
        missing = [c for c in base if c not in seen]
        if missing:
            routes.append(missing)
        k = max(1, int(round(strength)))
        if len(routes) >= 2:
            for _ in range(k):
                a, b = rng.sample(range(len(routes)), 2)
                ra, rb = routes[a], routes[b]
                for _try in range(4):
                    i1, j1 = self._segment(ra, rng)
                    i2, j2 = self._segment(rb, rng)
                    if j1 > i1 or j2 > i2:
                        break
                segA, segB = ra[i1:j1], rb[i2:j2]
                if rng.random() < 0.5:
                    segA = segA[::-1]
                if rng.random() < 0.5:
                    segB = segB[::-1]
                routes[a] = ra[:i1] + segB + ra[j1:]
                routes[b] = rb[:i2] + segA + rb[j2:]
                routes = [r for r in routes if r]
                if len(routes) < 2:
                    break
        else:
            r = routes[0]
            for _ in range(k):
                if len(r) >= 2:
                    i, j = sorted(rng.sample(range(len(r)), 2))
                    r = r[:i] + r[i:j + 1][::-1] + r[j + 1:]
            routes = [r]
        routes = [r[::-1] if rng.random() < self.route_reverse_prob else r for r in routes]
        if rng.random() < self.route_shuffle_prob:
            rng.shuffle(routes)
        tour = [c for r in routes for c in r]
        if tour == base:
            i, j = rng.sample(range(n), 2)
            tour = list(base)
            tour[i], tour[j] = tour[j], tour[i]
        return canonical(tour)


def build_component(problem, max_seg=3, route_shuffle_prob=0.5, route_reverse_prob=0.2):
    return RouteCrossExchangeReshuffle(
        problem,
        max_seg=max_seg,
        route_shuffle_prob=route_shuffle_prob,
        route_reverse_prob=route_reverse_prob,
    )
